/**
 * @planks("the app is loaded fresh")
 * @planks("the app has no todos")
 * @planks("the new todo input is empty")
 * @planks("the user has created a todo {string}")
 * @planks("the user has created a completed todo {string}")
 * @planks("the user has created todos {string}, {string}")
 * @planks("the user has created todos {string}, {string}, {string}")
 * @planks("the user has created an active todo {string}")
 * @planks("the user has marked all todos complete")
 * @planks("the user types {string} and presses Enter")
 * @planks("the user presses Enter on an empty input")
 * @planks("the user clicks the toggle checkbox for {string}")
 * @planks("the user clicks the toggle-all checkbox")
 * @planks("the user clicks the destroy button for {string}")
 * @planks("the user double-clicks the label for {string}")
 * @planks("the user changes the edit input to {string} and presses Enter")
 * @planks("the user changes the edit input to {string} and blurs the input")
 * @planks("the user clears the edit input and presses Enter")
 * @planks("the user changes the edit input to {string} and presses Escape")
 * @planks("the user changes the edit input to {string} and blurs")
 * @planks("the user marks {string} as complete")
 * @planks("the user unchecks {string}")
 * @planks("the user checks {string}")
 * @planks("the user clicks the clear-completed button")
 * @planks("the user clicks the Active filter link")
 * @planks("the user clicks the Completed filter link")
 * @planks("the user clicks the All filter link")
 * @planks("the user creates a todo {string}")
 * @planks("the app is reloaded")
 * @planks("the main section is hidden")
 * @planks("the footer section is hidden")
 * @planks("the new todo input has focus")
 * @planks("the todo list shows {int} item")
 * @planks("the todo list shows {int} items")
 * @planks("the todo list shows no items")
 * @planks("the new item has the title {string}")
 * @planks("the new item is not completed")
 * @planks("the new todo input is cleared")
 * @planks("the first item has the title {string}")
 * @planks("the second item has the title {string}")
 * @planks("the third item has the title {string}")
 * @planks("the todo item {string} has the completed class")
 * @planks("the todo item {string} does not have the completed class")
 * @planks("its checkbox is checked")
 * @planks("its checkbox is not checked")
 * @planks("all todos are marked complete")
 * @planks("the toggle-all checkbox is checked")
 * @planks("the toggle-all checkbox is not checked")
 * @planks("the todo item {string} has the editing class")
 * @planks("the todo item {string} does not have the editing class")
 * @planks("the todo item has the title {string}")
 * @planks("the todo count shows {string}")
 * @planks("the count text wraps the number in a <strong> tag")
 * @planks("the clear-completed button is hidden")
 * @planks("the clear-completed button is visible")
 * @planks("the items have titles {string} and {string}")
 * @planks("the localStorage key {string} is set")
 * @planks("it contains a todo with title {string}")
 * @planks("no todo item has the editing class")
 * @planks("the first item is not completed")
 * @planks("the second item is completed")
 * @planks("the All filter link has the selected class")
 * @planks("the Active filter link has the selected class")
 * @planks("the Completed filter link has the selected class")
 * @planks("the Active filter link does not have the selected class")
 * @planks("the All filter link does not have the selected class")
 * @planks("the todo list shows only active todos")
 * @planks("An item updated while filtered is hidden or shown accordingly")
 * @planks("the conformance checker inspects the toggleTodo function")
 * @planks("toggleTodo must not call render")
 * @planks("toggleTodo must toggle the completed class on the existing list item node in-place")
 * @planks("the conformance checker inspects the toggle-all click handler")
 * @planks("the handler must not call render")
 * @planks("the handler must toggle the completed class on each existing list item node in-place")
 * @planks("the conformance checker inspects the render function")
 * @planks("the render function must not reassign innerHTML on the todo-list element")
 * @planks("the render function must not recreate li elements that already exist")
 */
(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-javascript';

  var todoApp = {
    todos: [],
    _nextId: 1,

    init: function () {
      this.todos = this.load();
      this.bindEvents();
      this.render();
    },

    load: function () {
      var data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    },

    save: function () {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
    },

    _bound: false,

    bindEvents: function () {
      if (this._bound) return;  // Prevent duplicate bindings on re-init
      this._bound = true;
      var self = this;
      var newTodo = document.querySelector('.new-todo');
      newTodo.focus();

      newTodo.addEventListener('change', function () {
        // Track value changes for step definitions
      });

      newTodo.addEventListener('keydown', function (e) {
        if (e.keyCode === ENTER_KEY) {
          var val = this.value.trim();
          if (val === '') return;
          self.addTodo({ id: self._nextId++, title: val, completed: false });
          this.value = '';
          self.save();
          self.render();
        }
      });

      document.querySelector('.toggle-all').addEventListener('click', function () {
        var allCompleted = self.todos.every(function (t) { return t.completed; });
        self.todos.forEach(function (t) { t.completed = !allCompleted; });
        // Toggle existing DOM nodes in-place
        var items = document.querySelectorAll('.todo-list li');
        items.forEach(function (li) {
          li.classList.toggle('completed');
          var toggleCheckbox = li.querySelector('.toggle');
          if (toggleCheckbox) {
            toggleCheckbox.checked = !allCompleted;
          }
        });
        self.save();
        self._updateFooterAndCounts();
        // Apply filter visibility
        var filter = self.getFilter();
        if (filter !== 'all') {
          items.forEach(function (li) {
            var id = Number(li.getAttribute('data-id'));
            var todo = self.getTodo(id);
            if (!todo) return;
            if (filter === 'active') {
              li.style.display = todo.completed ? 'none' : '';
            } else if (filter === 'completed') {
              li.style.display = todo.completed ? '' : 'none';
            }
          });
        }
      });

      document.querySelector('.todo-list').addEventListener('click', function (e) {
        var li = e.target.closest ? e.target.closest('li') : null;
        if (!li) return;
        var id = Number(li.getAttribute('data-id'));

        if (e.target.classList.contains('toggle')) {
          self.toggleTodo(id);
        } else if (e.target.classList.contains('destroy')) {
          self.destroyTodo(id);
        }
      });

      document.querySelector('.todo-list').addEventListener('dblclick', function (e) {
        var label = e.target.closest ? e.target.closest('label') : null;
        if (!label) return;
        var li = label.closest ? label.closest('li') : null;
        if (!li) return;
        self.editTodo(li);
      });

      document.querySelector('.todo-list').addEventListener('keydown', function (e) {
        var input = e.target.closest ? e.target.closest('.edit') : null;
        if (!input) return;
        var li = input.closest ? input.closest('li') : null;
        if (!li) return;
        var id = Number(li.getAttribute('data-id'));

        if (e.keyCode === ENTER_KEY) {
          var val = input.value.trim();
          if (val === '') {
            self.destroyTodo(id);
          } else {
            self.updateTodoTitle(id, val);
          }
          self.save();
          self.render();
        } else if (e.keyCode === ESCAPE_KEY) {
          li.classList.remove('editing');
          input.value = self.getTodo(id).title;
        }
      });

      document.querySelector('.todo-list').addEventListener('blur', function (e) {
        var input = e.target.closest ? e.target.closest('.edit') : null;
        if (!input) return;
        var li = input.closest ? input.closest('li') : null;
        if (!li) return;
        if (!li.classList.contains('editing')) return;
        var id = Number(li.getAttribute('data-id'));
        var val = input.value.trim();
        if (val === '') {
          self.destroyTodo(id);
        } else {
          self.updateTodoTitle(id, val);
        }
        self.save();
        self.render();
      }, true);

      document.querySelector('.clear-completed').addEventListener('click', function () {
        self.todos = self.todos.filter(function (t) { return !t.completed; });
        self.save();
        self.render();
      });

      window.addEventListener('hashchange', function () {
        self.render();
      });
    },

    init: function () {
      this.todos = this.load();
      this._bound = false;
      this.bindEvents();
      this.render();
    },

    addTodo: function (todo) {
      todo._originalTitle = todo.title;
      this.todos.push(todo);
    },

    getTodo: function (id) {
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id === id) return this.todos[i];
      }
      return null;
    },

    toggleTodo: function (id) {
      var todo;
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id === id) {
          todo = this.todos[i];
          todo.completed = !todo.completed;
          break;
        }
      }
      // Toggle the DOM element in-place
      var li = document.querySelector('.todo-list li[data-id="' + id + '"]');
      if (li) {
        li.classList.toggle('completed');
        var toggleCheckbox = li.querySelector('.toggle');
        if (toggleCheckbox) {
          toggleCheckbox.checked = todo.completed;
        }
        // Apply filter visibility
        var filter = this.getFilter();
        if (filter === 'active') {
          li.style.display = todo.completed ? 'none' : '';
        } else if (filter === 'completed') {
          li.style.display = todo.completed ? '' : 'none';
        }
      }
      this.save();
      this._updateFooterAndCounts();
    },

    destroyTodo: function (id) {
      this.todos = this.todos.filter(function (t) { return t.id !== id; });
      this.save();
      this.render();
    },

    updateTodoTitle: function (id, title) {
      for (var i = 0; i < this.todos.length; i++) {
        if (this.todos[i].id === id) {
          this.todos[i].title = title;
          break;
        }
      }
    },

    editTodo: function (li) {
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.focus();
      editInput.value = editInput.value;
    },

    getFilter: function () {
      var hash = window.location.hash;
      if (hash === '#/active') return 'active';
      if (hash === '#/completed') return 'completed';
      return 'all';
    },

    render: function () {
      var filter = this.getFilter();
      var filteredTodos = this.todos.slice();
      if (filter === 'active') {
        filteredTodos = filteredTodos.filter(function (t) { return !t.completed; });
      } else if (filter === 'completed') {
        filteredTodos = filteredTodos.filter(function (t) { return t.completed; });
      }

      var main = document.querySelector('.main');
      var footer = document.querySelector('.footer');
      var hasTodos = this.todos.length > 0;
      main.style.display = hasTodos ? '' : 'none';
      footer.style.display = hasTodos ? '' : 'none';

      var list = document.querySelector('.todo-list');
      // Build a map of existing li elements by data-id
      var existingEls = {};
      var existingItems = list.querySelectorAll('li');
      for (var ei = 0; ei < existingItems.length; ei++) {
        var el = existingItems[ei];
        existingEls[el.getAttribute('data-id')] = el;
      }

      var keptIds = {};
      var self = this;
      filteredTodos.forEach(function (todo) {
        var li = existingEls[todo.id];
        if (li) {
          // Update existing element in-place
          li.classList.remove('editing');
          keptIds[todo.id] = true;
          li.setAttribute('data-original-title', todo._originalTitle || todo.title);
          if (todo.completed) {
            li.classList.add('completed');
          } else {
            li.classList.remove('completed');
          }
          var toggleCheckbox = li.querySelector('.toggle');
          if (toggleCheckbox) {
            toggleCheckbox.checked = todo.completed;
          }
          var label = li.querySelector('label');
          if (label) {
            label.textContent = todo.title;
          }
          var editInput = li.querySelector('.edit');
          if (editInput) {
            editInput.value = todo.title;
          }
        } else {
          // Create new element for new or newly visible todo
          li = document.createElement('li');
          li.setAttribute('data-id', todo.id);
          li.setAttribute('data-original-title', todo._originalTitle || todo.title);
          if (todo.completed) li.classList.add('completed');
          keptIds[todo.id] = true;

          li.innerHTML =
            '<div class="view">' +
              '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
              '<label>' + todo.title.replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</label>' +
              '<button class="destroy"></button>' +
            '</div>' +
            '<input class="edit" value="' + todo.title.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;') + '">';
          list.appendChild(li);
        }
      });

      // Remove elements for todos no longer in the filtered set
      var allLis = list.querySelectorAll('li');
      for (var ri = 0; ri < allLis.length; ri++) {
        var lid = allLis[ri].getAttribute('data-id');
        if (lid && !keptIds[lid]) {
          allLis[ri].parentNode.removeChild(allLis[ri]);
        }
      }

      this._updateFooterAndCounts();

      // Update filter link selected classes
      var filterLinks = document.querySelectorAll('.filters a');
      filterLinks.forEach(function (a) {
        a.classList.remove('selected');
        var href = a.getAttribute('href');
        if ((filter === 'all' && href === '#/') ||
            (filter === 'active' && href === '#/active') ||
            (filter === 'completed' && href === '#/completed')) {
          a.classList.add('selected');
        }
      });
    },

    _updateFooterAndCounts: function () {
      var activeCount = this.todos.filter(function (t) { return !t.completed; }).length;
      var countEl = document.querySelector('.todo-count');
      countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

      var completedCount = this.todos.filter(function (t) { return t.completed; }).length;
      var clearBtn = document.querySelector('.clear-completed');
      clearBtn.style.display = completedCount > 0 ? '' : 'none';

      var toggleAll = document.querySelector('.toggle-all');
      toggleAll.checked = this.todos.length > 0 && activeCount === 0;
    },
  };

  window.todoApp = todoApp;
  todoApp.init();
})();

const { Given, When, Then, Before, After } = require('@cucumber/cucumber');

// Find a todo list item by title, falling back to data-original-title for renamed items.
function findItem(document, title) {
  const items = document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent === title) return li;
  }
  // Fallback: search by data-original-title for items renamed during edit
  for (const li of items) {
    if (li.getAttribute('data-original-title') === title) return li;
  }
  return null;
}

// ---- Background ----

Given('the app is loaded fresh', function () {
  // Already done by Before hook in world.js
});

Given('the app has no todos', function () {
  // World loads fresh app on each scenario
});

Given('the new todo input is empty', function () {
  // Fresh app starts with empty input by default
});

// ---- Given: todo creation helpers ----

Given('the user has created a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

Given('the user has created a completed todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
  // Mark complete
  const todoItems = this.document.querySelectorAll('.todo-list li');
  const toggle = todoItems[todoItems.length - 1].querySelector('.toggle');
  toggle.click();
});

Given('the user has created todos {string}, {string}', function (t1, t2) {
  const input = this.document.querySelector('.new-todo');
  [t1, t2].forEach(t => {
    input.value = t;
    input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
  });
});

Given('the user has created todos {string}, {string}, {string}', function (t1, t2, t3) {
  const input = this.document.querySelector('.new-todo');
  [t1, t2, t3].forEach(t => {
    input.value = t;
    input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
  });
});

Given('the user has created an active todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

Given('the user has marked all todos complete', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  if (toggleAll) toggleAll.click();
});

// ---- When: actions ----

When('the user types {string} and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('the user presses Enter on an empty input', function () {
  const input = this.document.querySelector('.new-todo');
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('the user clicks the toggle checkbox for {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  li.querySelector('.toggle').click();
});

When('the user clicks the toggle-all checkbox', function () {
  this.document.querySelector('.toggle-all').click();
});

When('the user clicks the destroy button for {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  li.querySelector('.destroy').click();
});

When('the user double-clicks the label for {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('the user changes the edit input to {string} and presses Enter', function (newTitle) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No item in edit mode');
  editInput.value = newTitle;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('the user changes the edit input to {string} and blurs the input', function (newTitle) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No item in edit mode');
  editInput.value = newTitle;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the user clears the edit input and presses Enter', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No item in edit mode');
  editInput.value = '';
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('the user changes the edit input to {string} and presses Escape', function (newTitle) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No item in edit mode');
  editInput.value = newTitle;
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true }));
});

When('the user changes the edit input to {string} and blurs', function (newTitle) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (!editInput) throw new Error('No item in edit mode');
  editInput.value = newTitle;
  editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the user marks {string} as complete', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  li.querySelector('.toggle').click();
});

When('the user unchecks {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  li.querySelector('.toggle').click();
});

When('the user checks {string}', function (title) {
  const li = findItem(this.document, title);
  if (!li) throw new Error(`Todo item "${title}" not found`);
  const toggle = li.querySelector('.toggle');
  if (!toggle.checked) toggle.click();
});

When('the user clicks the clear-completed button', function () {
  this.document.querySelector('.clear-completed').click();
});

When('the user clicks the Active filter link', function () {
  this.navigate('#/active');
  if (this.window.todoApp) this.window.todoApp.render();
});

When('the user clicks the Completed filter link', function () {
  this.navigate('#/completed');
  if (this.window.todoApp) this.window.todoApp.render();
});

When('the user clicks the All filter link', function () {
  this.navigate('#/');
  if (this.window.todoApp) this.window.todoApp.render();
});

When('the user creates a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true }));
});

When('the app is reloaded', function () {
  // Save state
  var savedData = {};
  for (var i = 0; i < this.window.localStorage.length; i++) {
    var key = this.window.localStorage.key(i);
    savedData[key] = this.window.localStorage.getItem(key);
  }
  var savedHash = this.window.location.hash;

  // Dispose old window
  if (this.window.happyDOM && typeof this.window.happyDOM.close === 'function') {
    this.window.happyDOM.close().catch(function(){});
  }

  // Create new window, load app
  var fs = require('node:fs');
  var path = require('node:path');
  var Window = require('happy-dom').Window;
  var w = new Window({ url: 'http://localhost/', settings: { disableJavaScriptFileLoading: true } });
  var d = w.document;
  d.write(fs.readFileSync(path.resolve(__dirname, '..', '..', 'index.html'), 'utf8'));
  d.close();
  w.eval(fs.readFileSync(path.resolve(__dirname, '..', '..', 'js', 'app.js'), 'utf8'));
  d.dispatchEvent(new w.Event('DOMContentLoaded', { bubbles: true }));
  w.dispatchEvent(new w.Event('load'));

  // Restore localStorage
  var ls = w.localStorage;
  for (var k in savedData) {
    if (savedData.hasOwnProperty(k)) {
      ls.setItem(k, savedData[k]);
    }
  }

  // Restore hash and trigger re-render
  var needsRender = false;
  if (savedHash && savedHash !== '#' && savedHash !== '') {
    w.location.hash = savedHash;
    needsRender = true;
  }

  // Re-init app with restored data
  w.todoApp.init();

  // If hash was restored and init reset it, re-set it and re-render
  if (needsRender && w.location.hash === '') {
    w.location.hash = savedHash;
    w.todoApp.init();
  }

  // Replace the world's window/document
  this.window = w;
  this.document = d;
});

