const { Given, When, Then } = require('@cucumber/cucumber');
const fs = require('node:fs');
const path = require('node:path');

/**
 * Find a named method inside the todoApp IIFE in app.js.
 * Returns { body: string } or null.
 */
function findTodoAppFunction(source, name) {
  // Match patterns: "name: function(...)" inside the todoApp object
  const re = new RegExp('(' + name + ')\\s*:\\s*function\\s*\\(', 'g');
  let match;
  while ((match = re.exec(source)) !== null) {
    const startIdx = match.index;
    const braceStart = source.indexOf('{', startIdx);
    if (braceStart === -1) continue;
    let depth = 0;
    let endIdx = -1;
    for (let i = braceStart; i < source.length; i++) {
      if (source[i] === '{') depth++;
      if (source[i] === '}') {
        depth--;
        if (depth === 0) { endIdx = i; break; }
      }
    }
    if (endIdx === -1) continue;
    return { body: source.substring(startIdx, endIdx + 1) };
  }
  return null;
}

Given('the source at {string}', function (filePath) {
  const resolvedPath = path.resolve(__dirname, '..', '..', filePath);
  this.sourceCode = fs.readFileSync(resolvedPath, 'utf8');
  if (!this.sourceCode) {
    throw new Error('Could not read source file: ' + filePath);
  }
});

When('the conformance checker inspects the toggleTodo function', function () {
  const fn = findTodoAppFunction(this.sourceCode, 'toggleTodo');
  if (!fn) throw new Error('Could not find toggleTodo function in source');
  this.currentFunction = fn;
  this.currentFunctionName = 'toggleTodo';
});

