When('the conformance checker inspects the toggle-all click handler', function () {
  const source = this.sourceCode;
  // Find the bindEvents function first
  const bindEventsFn = findTodoAppFunction(source, 'bindEvents');
  if (!bindEventsFn) throw new Error('Could not find bindEvents function in source');

  // Within bindEvents body, find the toggle-all click handler
  const bindEventsBody = bindEventsFn.body;
  const toggleAllPattern = /querySelector\s*\(\s*['"]\.toggle-all['"]\s*\)\s*\.\s*addEventListener\s*\(\s*['"]click['"]\s*,\s*function\s*\([^)]*\)\s*\{/;
  const match = bindEventsBody.match(toggleAllPattern);
  if (!match) throw new Error('Could not find toggle-all click handler registration');

  const handlerDeclStart = match.index + match[0].length;
  const braceStart = bindEventsBody.indexOf('{', handlerDeclStart - 10);
  if (braceStart === -1) throw new Error('Could not find opening brace of toggle-all handler');

  // Count braces from braceStart+1 to find matching closing brace
  let depth = 1;
  let endIdx = -1;
  for (let i = braceStart + 1; i < bindEventsBody.length; i++) {
    if (bindEventsBody[i] === '{') depth++;
    if (bindEventsBody[i] === '}') {
      depth--;
      if (depth === 0) { endIdx = i; break; }
    }
  }
  if (endIdx === -1) throw new Error('Could not find end of toggle-all click handler');

  this.currentFunction = {
    body: bindEventsBody.substring(braceStart - 1, endIdx + 1)
  };
  this.currentFunctionName = 'toggleAllHandler';
});

Then('toggleTodo must not call render', function () {
  const body = this.currentFunction.body;
  if (/render\s*\(\s*\)/.test(body)) {
    throw new Error('toggleTodo calls render');
  }
});

